draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'brown';
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Rye Bread', W / 2, H / 2 - 70);
  ctx.font = '18px Arial';
  ctx.fillText('Dense & Nutritious', W / 2, H / 2 + 70);
  ctx.beginPath();
  ctx.arc(W / 2 - 60, H / 2 - 20, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2 + 60, H / 2 - 20, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 60, H / 2 - 20);
  ctx.lineTo(W / 2 - 60, H / 2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 + 60, H / 2 - 20);
  ctx.lineTo(W / 2 + 60, H / 2 + 20);
  ctx.stroke();
  ctx.restore();
}
